import * as fs from 'fs';
import * as readline from 'readline';

const rl = readline.createInterface({
  input: fs.createReadStream('C:/Users/ziani/.gemini/antigravity-ide/brain/b2c99fea-3c4e-42de-af09-ab5855a7fa4e/.system_generated/logs/transcript_full.jsonl'),
  crlfDelay: Infinity
});

rl.on('line', (line) => {
  if (line.includes('KOSOVO_METOHIJA_FEATURE') && line.includes('TargetFile')) {
    const obj = JSON.parse(line);
    console.log('Step index modifying historicalBorders:', obj.step_index);
    fs.writeFileSync(`scripts/step_modify_${obj.step_index}.json`, JSON.stringify(obj, null, 2));
  }
});
